const evidence = $json;
const instructions = `Sen Emre Cancioglu icin teknik LinkedIn taslaklari hazirlayan bir editorsun. Uzmanlik alanlari OT/IIoT, endustriyel yapay zeka, enerji yonetimi, uretim analitigi, OPC UA, MQTT, Unified Namespace, OT siber guvenlik ve teknik liderliktir.

DEGISMEZ KURALLAR:
1. Yalnizca verilen evidence_item icindeki bilgileri gercek calisma veya sonuc olarak kullan.
2. Yapilmamis isi yapilmis gibi anlatma; yeni metrik, musteri, tesis, odul, tarih, arac veya sonuc uretme.
3. proof_level=idea ise gecmis basari dili degil ogretici/gorus dili kullan.
4. kind=lab_demo ise yerel demo, simulasyon veya sentetik veri oldugunu acikca soyle.
5. confidentiality=anonymize ise sirket, tesis, hat, musteri ve kisi adi verme.
6. Her gecmis zamanli veya olculebilir iddiayi claims listesine ekle ve evidence id ile eslestir.
7. Iddia approved_claims icinde anlam olarak desteklenmiyorsa allowed=false yap ve metinde kullanma.
8. Turkce, dogal, teknik fakat anlasilir yaz. Kurumsal klise, asiri ovgu ve yapay etkilesim tuzagi kullanma.
9. 900-1500 karakter hedefle; kisa paragraflar, gerekirse 2-4 madde ve en fazla 5 hashtag kullan.
10. Emoji kullanma veya en fazla bir tane kullan. Tek bir samimi soru ile bitir.
11. risk_flags yalnizca gercek bir engelleyici sorun varsa tanimli hata kodlarini icersin. Aciklama, guvence veya inceleme notu ekleme. Sorun yoksa bos dizi dondur.`;
const riskCodes = ['PRIVATE_EVIDENCE','CONFIDENTIAL_DETAIL','UNMAPPED_CLAIM','UNSUPPORTED_METRIC','DEMO_NOT_DISCLOSED','EVIDENCE_ID_MISMATCH','ORGANIZATION_NAME_EXPOSED','CAUSALITY_OVERCLAIM'];
const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    pillar: { type: 'string', enum: ['OT_VERI_MIMARISI','ENDUSTRIYEL_AI','ENERJI_SURDURULEBILIRLIK','URETIMDE_GENAI','OT_SIBER_GUVENLIK','TEKNIK_LIDERLIK'] },
    hook: { type: 'string' },
    body: { type: 'string' },
    cta: { type: 'string' },
    hashtags: { type: 'array', items: { type: 'string' } },
    claims: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          claim: { type: 'string' },
          evidence_id: { type: 'string' },
          allowed: { type: 'boolean' },
          reason: { type: 'string' }
        },
        required: ['claim','evidence_id','allowed','reason']
      }
    },
    image_brief: { type: 'string' },
    risk_flags: { type: 'array', items: { type: 'string', enum: riskCodes } }
  },
  required: ['pillar','hook','body','cta','hashtags','claims','image_brief','risk_flags']
};
return [{ json: { request_body: {
  model: 'gpt-6.1-terra',
  reasoning: { effort: 'low' },
  instructions,
  input: [{ role: 'user', content: [{ type: 'input_text', text: `evidence_item:\n${JSON.stringify(evidence)}` }] }],
  text: { format: { type: 'json_schema', name: 'linkedin_post_draft', strict: true, schema } },
  store: false
} } }];

const requestBody = { ...$json.request_body };
requestBody.instructions = `${requestBody.instructions}\n12. Telegram'da gorsel, tam metin ve dugmeler tek mesajda gosterilecek. hook, body ve cta alanlarinin toplam uzunlugu 650-780 karakter arasinda olmali; 780 karakteri kesinlikle asma. Kaynak URL ve hashtagler bu sinira dahil degildir.`;
return [{ json: { request_body: requestBody } }];

const response = $json;
if (response.error) throw new Error(`OpenAI error: ${JSON.stringify(response.error)}`);
if (response.status && response.status !== 'completed') throw new Error(`OpenAI response status: ${response.status}`);
const message = (response.output ?? []).find((item) => item.type === 'message');
const refusal = message?.content?.find((item) => item.type === 'refusal');
if (refusal) throw new Error(`OpenAI refusal: ${refusal.refusal}`);
const outputText = message?.content?.find((item) => item.type === 'output_text')?.text;
if (!outputText) throw new Error('OpenAI output_text bulunamadi');
const draft = JSON.parse(outputText);
const evidence = $('Reserve Evidence').first().json;
const required = ['pillar','hook','body','cta','hashtags','claims','image_brief','risk_flags'];
for (const key of required) {
  if (!(key in draft)) throw new Error(`Taslak alani eksik: ${key}`);
}
if (!Array.isArray(draft.hashtags) || draft.hashtags.length > 5) draft.risk_flags.push('HASHTAG_LIMIT');
if (!Array.isArray(draft.claims)) throw new Error('claims dizi olmali');
if (!Array.isArray(draft.risk_flags)) throw new Error('risk_flags dizi olmali');
const text = `${draft.hook}\n${draft.body}\n${draft.cta}`;
const numericClaim = /(?:%|yuzde|\b\d+(?:[.,]\d+)?\b)/i.test(text.replace(/4\.0/g, ''));
if (numericClaim && !draft.claims.some((claim) => claim.allowed)) draft.risk_flags.push('UNMAPPED_NUMERIC_CLAIM');
if (draft.claims.some((claim) => !claim.allowed)) draft.risk_flags.push('DISALLOWED_CLAIM');
if (evidence.kind === 'lab_demo' && !/(demo|simulasyon|sentetik)/i.test(text)) draft.risk_flags.push('DEMO_NOT_DISCLOSED');
if (evidence.confidentiality === 'private') draft.risk_flags.push('PRIVATE_EVIDENCE');
for (const claim of draft.claims) {
  if (claim.evidence_id !== evidence.id) {
    claim.allowed = false;
    claim.reason = 'Evidence ID eslesmiyor';
    draft.risk_flags.push('EVIDENCE_ID_MISMATCH');
  }
}
const uniqueRisks = [...new Set(draft.risk_flags.filter(Boolean))];
const approvalStatus = uniqueRisks.length ? 'blocked' : 'needs_review';
return [{ json: {
  evidence_id: evidence.id,
  pillar: draft.pillar,
  hook: draft.hook.trim(),
  body: draft.body.trim(),
  cta: draft.cta.trim(),
  hashtags: draft.hashtags,
  claims: draft.claims,
  image_brief: draft.image_brief.trim(),
  risk_flags: uniqueRisks,
  approval_status: approvalStatus,
  text_model: response.model ?? 'gpt-6.1-terra',
  openai_response_id: response.id ?? null,
  token_usage: response.usage ?? null
} }];

const draft = { ...$json };
const sourceRef = String($('Reserve Evidence').first().json.source_ref || '').trim();
const combined = `${draft.hook || ''} ${draft.body || ''} ${draft.cta || ''}`;
if (/^https?:\/\//i.test(sourceRef) && !combined.includes(sourceRef)) {
  draft.cta = `${String(draft.cta || '').trim()}\n\nKaynak: ${sourceRef}`.trim();
}
return [{ json: draft }];
